def copy_im_accounts(apps, schema_editor):
    """把客户原单一 IM 字段迁移到 CustomerIMAccount 子表。"""
    Customer = apps.get_model('customer_manager', 'Customer')
    CustomerIMAccount = apps.get_model('customer_manager', 'CustomerIMAccount')
    for c in Customer.objects.all():
        im_type = getattr(c, 'im_type', '') or ''
        account = getattr(c, 'im_account', '') or ''
        group = getattr(c, 'im_group', '') or ''
        if im_type or account or group:
            CustomerIMAccount.objects.create(
                customer=c,
                im_type=im_type or 'other',
                account=account,
                group=group,
                is_primary=True,
            )


